/* Fixed-version entry. Configure the base after choosing your repository. */
(() => {
  const doc=(window.parent||window).document,base="https://cdn.jsdelivr.net/gh/xgdddl/fourth-disaster-panel@v1.3.11/";
  let pending=false;
  async function load(){
    if(pending)return;
    if(doc.getElementById('aelderan-unified-shell'))return;
    if(base.includes('GITHUB_OWNER')){show('还未指定 GitHub 仓库；请先使用离线完整版。');return;}
    pending=true;doc.getElementById('aeu-load-error')?.remove();
    try{await import(base+'dist/index.js');}
    catch(error){console.warn('[第四天灾静态加载]',error);show('第四天灾加载失败。请检查网络后重试，或停用此入口、启用离线完整版。存档和 API 设置不会被清空。');}
    finally{pending=false;}
  }
  function show(message){
    doc.getElementById('aeu-load-error')?.remove();const box=doc.createElement('div');box.id='aeu-load-error';box.setAttribute('role','alert');
    box.style.cssText='position:fixed;z-index:2147483647;bottom:18px;left:50%;transform:translateX(-50%);width:min(420px,calc(100vw - 28px));padding:16px;background:#242820;color:#f2e6c9;border:1px solid #b79a63;font:13px/1.8 sans-serif;box-shadow:0 5px 30px #0008';
    const text=doc.createElement('p');text.textContent=message;box.appendChild(text);
    for(const [label,action]of [['重新加载',load],['收起提示',()=>box.remove()]]){const b=doc.createElement('button');b.textContent=label;b.style.cssText='padding:7px 12px;margin-right:8px;background:#373e32;color:#f2e6c9;border:1px solid #ad945e;cursor:pointer';b.addEventListener('click',action);box.appendChild(b);}doc.body.appendChild(box);
  }
  load();window.addEventListener('pagehide',()=>doc.getElementById('aeu-load-error')?.remove(),{once:true});
})();
